@media (max-width:768px){.mpcrm-order-detail-summary,.mpcrm-order-detail-grid{grid-template-columns:1fr}.mpcrm-order-detail-head{flex-direction:column}}
.mpcrm-item-cell{width:280px;max-width:280px}
