.mpcrm-wa-status-ok{background:#dcfce7;color:#166534}.mpcrm-wa-status-failed{background:#fee2e2;color:#991b1b}.mpcrm-wa-status-pending{background:#fef3c7;color:#92400e}.mpcrm-wa-status-none{background:#f1f5f9;color:#64748b}
