.mpcrm-map-result-code{font:800 .72rem ui-monospace,SFMono-Regular,Menlo,monospace;color:#0f172a}.mpcrm-map-result-name{font-size:.72rem;color:#64748b;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
