.mpcrm-toolbar{background:#fff;border:1px solid #e5e7eb;border-radius:14px;padding:12px}.mpcrm-toolbar .form-label{color:#64748b;letter-spacing:.02em}.mpcrm-toolbar .form-control,.mpcrm-toolbar .form-select{border-color:#dbe3ec}.mpcrm-toolbar .form-control:focus,.mpcrm-toolbar .form-select:focus{border-color:#93c5fd;box-shadow:0 0 0 .16rem rgba(59,130,246,.1)}
.mpcrm-filter-toggle{display:flex;align-items:center;width:100%;padding:.45rem .6rem;border:1px solid #e2e8f0;border-radius:8px;background:#f8fafc;color:#334155;font-size:.72rem;font-weight:800;text-align:left;cursor:pointer}.mpcrm-filter-toggle:hover,.mpcrm-filter-toggle.is-open{border-color:#bfdbfe;background:#eff6ff;color:#1d4ed8}.mpcrm-filter-toggle-note{margin-left:.45rem;color:#94a3b8;font-size:.66rem;font-weight:600}.mpcrm-filter-toggle>i:last-child{transition:transform .15s ease}.mpcrm-filter-toggle.is-open>i:last-child{transform:rotate(180deg)}
.mpcrm-advanced-filters{padding:.65rem;border:1px solid #e2e8f0;border-radius:10px;background:#f8fafc}
