.mpcrm-chart-grid{display:grid;grid-template-columns:repeat(var(--chart-columns),minmax(18px,1fr));align-items:end;gap:clamp(2px,.55vw,8px);height:190px;padding:4px 4px 0;background:repeating-linear-gradient(to bottom,transparent 0,transparent 45px,#e2e8f0 46px);border-bottom:1px solid #cbd5e1}
