.mpcrm-analysis-row-head{display:flex;align-items:center;justify-content:space-between;gap:.75rem;margin-bottom:5px;font-size:.7rem;color:#475569}.mpcrm-analysis-row-head span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.mpcrm-analysis-row-head b{padding:.16rem .42rem;border-radius:999px;background:#f1f5f9;color:#475569;font-size:.65rem;font-weight:800;white-space:nowrap}.mpcrm-analysis-row-meta{margin-top:4px;color:#94a3b8;font-size:.63rem;font-weight:650;line-height:1.1}
