.mpcrm-analysis-row-expandable{cursor:pointer;border-radius:8px;padding:3px 5px;margin:-3px -5px;transition:background .15s ease}.mpcrm-analysis-row-expandable:hover,.mpcrm-analysis-row-expandable:focus-visible{background:#f8fafc;outline:none}.mpcrm-city-toggle-icon{color:#64748b;font-size:.65rem;transition:transform .15s ease}.mpcrm-analysis-row-expandable.is-expanded .mpcrm-city-toggle-icon{transform:rotate(180deg)}.mpcrm-city-breakdown{display:grid;gap:9px;max-height:240px;overflow-y:auto;padding:10px 5px 3px;border-top:1px solid #f1f5f9}.mpcrm-analysis-row-sub{padding-left:8px}
