.mpcrm-eyebrow>span:not(.mpcrm-eyebrow-mark){color:#cbd5e1}.mpcrm-eyebrow-mark{width:7px;height:7px;border-radius:50%;background:#2563eb;box-shadow:0 0 0 4px #dbeafe}
