.mpcrm-filter-card{padding:16px 18px 18px;border-color:#dbe3ec;border-radius:16px;box-shadow:0 8px 22px rgba(15,23,42,.035)}.mpcrm-filter-head{display:flex;align-items:center;justify-content:space-between;gap:1rem;margin-bottom:15px}.mpcrm-filter-title{margin:.25rem 0 0;color:#0f172a;font-size:.95rem;font-weight:850}.mpcrm-filter-meta{display:flex;align-items:center;gap:.75rem}.mpcrm-filter-count{display:inline-flex;align-items:center;gap:.35rem;border-radius:999px;padding:.3rem .55rem;background:#f1f5f9;color:#475569;font-size:.66rem;font-weight:800}.mpcrm-filter-hint{color:#94a3b8;font-size:.67rem}.mpcrm-field-label{display:block;margin-bottom:.4rem;color:#475569;font-size:.68rem;font-weight:800}.mpcrm-input-wrap{position:relative}.mpcrm-input-wrap>i{position:absolute;left:.72rem;top:50%;z-index:2;transform:translateY(-50%);color:#94a3b8;font-size:.78rem;pointer-events:none}.mpcrm-input-wrap>.form-control{padding-left:2.1rem}.mpcrm-filter-card .form-control,.mpcrm-filter-card .form-select{height:38px;border:1px solid #dbe3ec;border-radius:9px;color:#334155;font-size:.74rem;font-weight:650;box-shadow:none}.mpcrm-filter-card .form-control::placeholder{color:#94a3b8;font-weight:500}.mpcrm-filter-card .form-control:focus,.mpcrm-filter-card .form-select:focus{border-color:#60a5fa;box-shadow:0 0 0 .18rem rgba(37,99,235,.1)}.mpcrm-apply-btn{height:38px;border:1px solid #0f172a;border-radius:9px;background:#0f172a;color:#fff;font-size:.72rem;font-weight:800}.mpcrm-apply-btn:hover{background:#1e293b;color:#fff}.mpcrm-reset-btn{display:grid;place-items:center;width:38px;height:38px;border:1px solid #dbe3ec;border-radius:9px;color:#64748b;background:#fff}.mpcrm-reset-btn:hover{border-color:#94a3b8;color:#0f172a;background:#f8fafc}
